// src/pages/AgendarPage.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { listarBloquesPorEspecialidad, reservarBloque, crearConsulta } from '../service/api';

const ESPECIALIDADES = [
  'cardiologia', 'dermatologia', 'gastroenterologia', 'ginecologia',
  'medicina general', 'neurologia', 'oftalmologia', 'ortopedia',
  'otorrinolaringologia', 'pediatria', 'psiquiatria', 'traumatologia', 'urologia',
];

const PASOS = [
  { num: 1, label: 'Especialidad' },
  { num: 2, label: 'Horario' },
  { num: 3, label: 'Confirmar' },
];

export default function AgendarPage() {
  const { usuario } = useAuth();
  const navigate = useNavigate();

  const [paso, setPaso] = useState(1);
  const [especialidad, setEspecialidad] = useState('');
  const [bloques, setBloques] = useState([]);
  const [bloqueSeleccionado, setBloqueSeleccionado] = useState(null);
  const [sintomas, setSintomas] = useState('');
  const [nombrePaciente, setNombrePaciente] = useState('');
  const [loading, setLoading] = useState(false);
  const [reservando, setReservando] = useState(false);
  const [error, setError] = useState('');
  const [exito, setExito] = useState(false);

  useEffect(() => {
    if (!especialidad) return;
    setLoading(true);
    setError('');
    setBloques([]);
    setBloqueSeleccionado(null);
    listarBloquesPorEspecialidad(especialidad)
      .then(data => setBloques(Array.isArray(data) ? data : []))
      .catch(() => setError('No se pudieron cargar los bloques disponibles.'))
      .finally(() => setLoading(false));
  }, [especialidad]);

  const handleSeleccionarEspecialidad = (esp) => {
    setEspecialidad(esp);
    setPaso(2);
  };

  const handleSeleccionarBloque = (bloque) => {
    setBloqueSeleccionado(bloque);
    setPaso(3);
  };

  const handleConfirmar = async () => {
    if (!bloqueSeleccionado || !sintomas || !nombrePaciente) {
      setError('Completa todos los campos antes de confirmar.');
      return;
    }
    setReservando(true);
    setError('');
    try {
      await crearConsulta({
        usuarioId: usuario.id,
        nombrePaciente,
        especialidad,
        sintomas,
        bloquesAgendaId: bloqueSeleccionado.bloquesAgendaid,
        fechaCita: bloqueSeleccionado.fechaHora,
        estado: 'AGENDADA',
      });
      await reservarBloque(bloqueSeleccionado.bloquesAgendaid);
      setExito(true);
    } catch {
      setError('Error al confirmar la cita. El bloque puede haber sido tomado por otro usuario.');
    } finally {
      setReservando(false);
    }
  };

  const formatFecha = (fechaHora) => {
    const d = new Date(fechaHora);
    return {
      dia: d.toLocaleDateString('es-CL', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' }),
      hora: d.toLocaleTimeString('es-CL', { hour: '2-digit', minute: '2-digit' }),
    };
  };

  // Pantalla éxito
  if (exito) {
    return (
      <div className="page agendar-exito">
        <div className="agendar-exito-icon">✅</div>
        <h2 className="page-title">¡Cita agendada con éxito!</h2>
        <p style={{ color: 'var(--text-secondary)', marginBottom: 8 }}>
          Tu cita de <strong>{especialidad}</strong> fue confirmada para:
        </p>
        <div className="card agendar-exito-card">
          <div className="agendar-exito-fecha">
            {formatFecha(bloqueSeleccionado.fechaHora).dia}
          </div>
          <div className="agendar-exito-hora">
            {formatFecha(bloqueSeleccionado.fechaHora).hora} hrs
          </div>
          <div className="agendar-exito-doctor">
            🩺 Dr. {bloqueSeleccionado.profesionalId}
          </div>
        </div>
        <button className="btn-primary" onClick={() => navigate('/mis-consultas')}>
          Ver mis consultas
        </button>
      </div>
    );
  }

  return (
    <div className="page agendar-page">

      <h2 className="page-title">📅 Agendar cita médica</h2>

      {/* Indicador de pasos */}
      <div className="agendar-pasos">
        {PASOS.map((p, i) => (
          <React.Fragment key={p.num}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <div className={`agendar-paso-num ${paso >= p.num ? 'activo' : ''}`}>
                {p.num}
              </div>
              <span className={`agendar-paso-label ${paso === p.num ? 'activo' : ''}`}>
                {p.label}
              </span>
            </div>
            {i < PASOS.length - 1 && (
              <div className={`agendar-paso-linea ${paso > p.num ? 'completado' : ''}`} />
            )}
          </React.Fragment>
        ))}
      </div>

      {error && <div className="alert alert-error">⚠️ {error}</div>}

      {/* Paso 1 — Especialidad */}
      {paso === 1 && (
        <div className="card">
          <h3 style={{ fontWeight: 700, marginBottom: 20, fontSize: 16 }}>
            Selecciona la especialidad médica
          </h3>
          <div className="agendar-especialidades-grid">
            {ESPECIALIDADES.map(esp => (
              <button
                key={esp}
                className={`agendar-esp-btn ${especialidad === esp ? 'seleccionado' : ''}`}
                onClick={() => handleSeleccionarEspecialidad(esp)}
              >
                {esp}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Paso 2 — Bloques horarios */}
      {paso === 2 && (
        <div className="card">
          <div className="agendar-section-header">
            <h3>
              Horarios disponibles — <span>{especialidad}</span>
            </h3>
            <button
              className="agendar-btn-volver"
              onClick={() => { setPaso(1); setEspecialidad(''); }}
            >
              ← Cambiar
            </button>
          </div>

          {loading ? (
            <div className="spinner">Cargando bloques disponibles...</div>
          ) : bloques.length === 0 ? (
            <div className="agendar-sin-bloques">
              <div className="agendar-sin-icon">😔</div>
              <p>Sin horarios disponibles</p>
              <p>No hay bloques para {especialidad} en este momento.</p>
              <button
                className="btn-primary"
                style={{ marginTop: 16 }}
                onClick={() => { setPaso(1); setEspecialidad(''); }}
              >
                Elegir otra especialidad
              </button>
            </div>
          ) : (
            <div className="agendar-bloques-grid">
              {bloques.map(bloque => {
                const { dia, hora } = formatFecha(bloque.fechaHora);
                return (
                  <button
                    key={bloque.bloquesAgendaid}
                    className="agendar-bloque-btn"
                    onClick={() => handleSeleccionarBloque(bloque)}
                  >
                    <div className="agendar-bloque-disponible">✅ Disponible</div>
                    <div className="agendar-bloque-hora">{hora} hrs</div>
                    <div className="agendar-bloque-dia">{dia}</div>
                    <div className="agendar-bloque-doctor">🩺 Dr. {bloque.profesionalId}</div>
                  </button>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Paso 3 — Confirmar */}
      {paso === 3 && bloqueSeleccionado && (
        <div className="card">
          <div className="agendar-section-header">
            <h3>Confirma tu cita</h3>
            <button
              className="agendar-btn-volver"
              onClick={() => { setPaso(2); setBloqueSeleccionado(null); }}
            >
              ← Cambiar horario
            </button>
          </div>

          <div className="agendar-resumen">
            <div className="agendar-resumen-label">Cita seleccionada</div>
            <div className="agendar-resumen-especialidad">{especialidad}</div>
            <div className="agendar-resumen-hora">
              {formatFecha(bloqueSeleccionado.fechaHora).hora} hrs — {formatFecha(bloqueSeleccionado.fechaHora).dia}
            </div>
            <div className="agendar-resumen-doctor">
              🩺 Dr. {bloqueSeleccionado.profesionalId}
            </div>
          </div>

          <div className="form-group">
            <label>Tu nombre completo</label>
            <input
              className="form-control"
              placeholder="Ej: Juan Pérez González"
              value={nombrePaciente}
              onChange={e => setNombrePaciente(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Describe tus síntomas</label>
            <textarea
              className="form-control"
              placeholder="Describe detalladamente lo que estás sintiendo..."
              value={sintomas}
              onChange={e => setSintomas(e.target.value)}
              style={{ minHeight: 100 }}
              required
            />
          </div>

          <div className="agendar-confirmar-btns">
            <button
              className="btn-primary"
              onClick={handleConfirmar}
              disabled={reservando || !nombrePaciente || !sintomas}
            >
              {reservando ? 'Confirmando...' : '✅ Confirmar cita'}
            </button>
            <button
              className="btn-outline-teal"
              onClick={() => navigate('/mis-consultas')}
            >
              Cancelar
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
